feedback_kb.client_script:
api.controller = function($scope, $location, $element, $timeout) {
    var c = this;
    c.data.showSuccessful = false;
    c.data.hasErrors = false;
    c.data.rating = 0;
    c.data.url = window.location.href;
    var feedbackElement = $element.find('#feedback-body');
    if (c.data.openOnLoad == 'true' || c.data.autoExpandedPages.indexOf($location.search().id) > -1) {
        feedbackElement.collapse('show');
    }
    $scope.$on('$locationChangeSuccess', function() {
        if (c.data.autoExpandedPages.indexOf($location.search().id) > -1) {
            feedbackElement.collapse('show');
        } else {
            feedbackElement.collapse('hide');
        }
    });
    c.scrollTop = function() {
        document.querySelector('header').scrollIntoView({
            behavior: "smooth"
        });
        feedbackElement.collapse('hide');
    };
    c.expRatClick = function(_rating) {
        c.data.errorRating = false;
        if (c.data.hasErrors === true && c.data.errorEmail !== true) {
c.data.hasErrors = false;
        }
        switch (_rating) {
            case 'very easy':
                c.data.rating = 5;
                break;
            case 'easy':
                c.data.rating = 4;
                break;
            case 'okay':
                c.data.rating = 3;
                break;
            case 'difficult':
                c.data.rating = 2;
                break;
            case 'very difficult':
                c.data.rating = 1;
                break;
        }
    };
    c.submitFeedback = function($event) {
$event.preventDefault();
        if (!c.data.url) {
            c.data.url = window.location.href;
        }
        c.data.hasErrors = c.validate() !== true;
        if (c.data.hasErrors == false) {
            c.server.update().then(function() {
                if (c.data.success == 'true') {
                    c.data.showSuccessful = true;
                    $timeout(function() {
                        var successAlert = $element[0].querySelector('.feedback-success');
                        if (successAlert) {
                            successAlert.scrollIntoView();
                        }
                    }, 10);
                }
            });
        } else {
            $timeout(function() {
                var errorAlert = $element[0].querySelector('#feedback-kb-alert_box');
                if (errorAlert) {
                    errorAlert.scrollIntoView({
                        behavior: 'smooth'
                    });
                }
            }, 50);
            return false;
        }
    };
    c.clearAndHide = function() {
        var formElement = feedbackElement.find('form');
        if (formElement.length === 1) {
            formElement[0].reset();
        }
		c.data.rating = 0;
        c.data.suggestedImprovement = '';
		c.data.email = null;
        c.data.hasErrors = false;
        c.data.errorEmail = false;
        c.data.errorRating = false;
    };
    c.validate = function() {
        var isValid = true;
        if (c.isValidEmail(c.data.email) === false) {
            c.data.errorEmail = true;
            isValid = false;
        } else {
            c.data.errorEmail = false;
        }
        if (c.data.rating === 0) {
            isValid = false;
            c.data.errorRating = true;
        } else {
            c.data.errorRating = false;
        }
        return isValid;
    };
    c.isValidEmail = function(emailAddress) {
        var isValid = true;
        if (typeof emailAddress === 'string' &&
emailAddress.match(/^(?![\.])[a-zA-Z0-9!#$%*\/?|^{}`~&'\+\-=_.]+[^.\s@]@(?![\.-])[a-zA-Z0-9-_\.]+(\.[a-zA-Z0-9_]+)$/) === null) {
            isValid = false;
        }
        if (c.data.errorEmail === true && isValid === true) {
            c.data.errorEmail = false;
            if (c.data.errorRating !== true) {
c.data.hasErrors = false;
            }
        }
        return isValid;
    };
};

