				$location.search('id', 'selling');
				break;
			case 'information_for_buyers':
				$location.search('id', 'buying');
				break;
		}
	}

	if (c.data.isLoggedIn) {
		c.redirectLI();
	} else {
		c.redirectLO();
	}


};

