widget.client_script:
api.controller = function($scope, $rootScope, $timeout) {
    var c = this;
    c.showResults = false;
    c.hideFilter = true;
    c.filters = c.data.filters;
    if (c.filters && c.filters.opp_agency && c.filters.opp_agency.value) {
        c.selAgency = c.filters.opp_agency.value.label;
    }
    c.srch = function() {
        if (c.selAgency && c.selAgency.length > 0) {
            c.searching = true;
        } else {
            c.searching = !c.searching;
        }
    };
    c.scrollTo = function(elementName) {
        var element = document.querySelector(elementName);
        if (!element) {
            return;
        }
        element.scrollIntoView({
            behavior: "smooth",
            block: "center",
            inline: "nearest"
        });
    };
    c.showHideFilter = function(value) {
        c.hideFilter = value;
    };
    c.updateFilters = function() {
        c.checkStatus();
        c.filters.opps_filtered = isFiltered();
        c.data.filters = c.filters;
        c.server.update().then(function() {
            $rootScope.$broadcast('op.filter.updated', c.data.filters);
        });
    };
    c.clearFilter = function() {
        resetVals();
        c.filters.opp_agency.value = '';
        c.selAgency = '';
        c.filters.opp_keyword.value = '';
        c.deselectAllCats();
        c.deselectAllMPs();
        c.updateFilters();
    };
    c.agencySelected = function(agcy) {
        c.filters.opp_agency.value = agcy;
        c.selAgency = agcy.label;
        c.searching = false;
        c.updateFilters();
    };
    $scope.clearAgcy = function() {
        c.filters.opp_agency.value = '';
        c.selAgency = '';
        c.updateFilters();
    };
    c.mpSelectedRFQ = function(mp) {
        var mps = c.filters.opp_mps_rfq.choices;
        var all = true;
        var switchtoAll = false;
        if (mp.value == 'all' && mp.selected == true) {
            switchtoAll = true;
        } else if (mp.value == 'all' && mp.selected == false) {
            c.updateFilters();
            return;
        }
        for (var i = 0; i < mps.length; i++) {
            if (mps[i].value == 'all') {
                continue;
            }
            if (switchtoAll == true) {
                mps[i].selected = false;
            } else {
                if (mps[i].selected == true) {
                    all = false;
                    break;
                }
            }
        }
        mps[0].selected = all;
        if (all == true) {
            c.deselectAllCats();
        }
        c.updateFilters();
    };
    c.mpSelectedRFI = function(mp) {
        var mps = c.filters.opp_mps_rfi.choices;
        var all = true;
        var switchtoAll = false;
        if (mp.value == 'all' && mp.selected == true) {
            switchtoAll = true;
        } else if (mp.value == 'all' && mp.selected == false) {
            c.updateFilters();
            return;
        }
        for (var i = 0; i < mps.length; i++) {
            if (mps[i].value == 'all') {
                continue;
            }
            if (switchtoAll == true) {
                mps[i].selected = false;
            } else {
                if (mps[i].selected == true) {
                    all = false;
                    break;
                }
            }
        }
        mps[0].selected = all;
        c.updateFilters();
    };
    c.catSelected = function(mp, cat) {
        var cats = mp.categories;
        var all = true;
        var switchtoAll = false;
        if (cat.value == 'all' && cat.selected == true) {
            switchtoAll = true;
        }
        for (var i = 0; i < cats.length; i++) {
            if (cats[i].value == 'all') {
                continue;
            }
            if (switchtoAll == true) {
                cats[i].selected = false;
            } else {
                if (cats[i].selected == true) {
                    all = false;
                    break;
                }
            }
        }
        cats[0].selected = all;
        c.updateFilters();
    };
    c.deselectAllCats = function(mp) {
        var MPs = [];
        if (mp) {
            MPs = c.filters.opp_mps_rfq.choices.filter(function(m) {
                return m.sys_id == mp;
            });
        } else {
            MPs = c.filters.opp_mps_rfq.choices;
        }
        for (var m = 0; m < MPs.length; m++) {
            var cats = MPs[m].categories;
            for (var mc = 0; mc < cats.length; mc++) {
                if (cats[mc].defValue) {
                    cats[mc].selected = true;
                } else {
                    cats[mc].selected = false;
                }
            }
        }
    };
    c.deselectAllMPs = function() {
        var MPs = c.filters.opp_mps_rfq.choices;
        for (var m = 0; m < MPs.length; m++) {
            if (MPs[m].defValue) {
                MPs[m].selected = true;
            } else {
                MPs[m].selected = false;
            }
        }
        var MPRs = c.filters.opp_mps_rfi.choices;
        for (var n = 0; n < MPRs.length; n++) {
            if (MPRs[n].defValue) {
                MPRs[n].selected = true;
            } else {
                MPRs[n].selected = false;
            }
        }
    };
    c.checkMPs = function() {
        var rfq = c.filters.opp_mps_rfq.choices.filter(function(f) {
            return f.selected == true && !f.defValue;
        });
        if (!rfq || rfq.length == 0) {
            c.filters.opp_mps_rfq.choices[0].selected = true;
            c.deselectAllCats();
        } else {
            for (var i = 0; i < rfq.length; i++) {
                var cats = rfq[i].categories.filter(function(c) {
                    return c.selected == true;
                });
                if (!cats || cats.length == 0) {
                    rfq[i].categories[0].selected = true;
                }
            }
        }
        var rfi = c.filters.opp_mps_rfi.choices.filter(function(f) {
            return f.selected == true;
        });
        if (!rfi.length) {
            c.filters.opp_mps_rfi.choices[0].selected = true;
        }
    };
    c.checkStatus = function() {
        var st = c.filters.opp_status.choices;
        var selSt = st.filter(function(s) {
            return s.selected == true;
        });
        if (!selSt || selSt == [] || selSt == '') {
            st[0].selected = true;
        }
    };
    var clearAllListener = $rootScope.$on('op.clearall.update', function(event) {
        c.clearFilter();
    });
    var keywordListener = $rootScope.$on('op.keyword.update', function(event, data) {
        c.filters.opp_keyword.value = data;
        c.updateFilters();
    });
    var tileListener = $rootScope.$on('op.tileview.update', function(event, value) {
        c.filters.tileview = value;
        c.updateFilters();
    });
    var tagListener = $rootScope.$on('op.tag.update', function(event, tag) {
        if (tag.tag.type == 'agency') {
            c.filters[tag.tag.filter_name].value = '';
            c.selAgency = '';
        } else if (tag.tag.type == 'cats') {
            var mps = c.filters.opp_mps_rfq.choices;
            for (var i = 0; i < mps.length; i++) {
                var cat = mps[i].categories.filter(function(c) {
                    return c.value == tag.element.value;
                });
                if (cat && cat.length)
                    cat[0].selected = false;
            }
        } else {
            var choice = c.filters[tag.tag.filter_name].choices.filter(function(e) {
                return (e.sys_id && e.sys_id == tag.element.sys_id) || (e.value && e.value == tag.element.value);
            });
            if (choice && choice.length) {
                choice[0].selected = false;
            }
            if (tag.tag.filter_name == 'opp_mps_rfq') {
                c.deselectAllCats(tag.element.sys_id);
            }
        }
        c.checkMPs();
        c.updateFilters();
    });
    var showHideListener = $rootScope.$on('op.showhidefilter', function(event, data) {
        c.showHideFilter(false);
        $timeout(
            function() {
$('#closeSideBar').focus();
            }
        );
    });
    $(document).on('click', function(event) {
        if (!$(event.target).closest('#agencyRPdiv').length) {
            if (c.searching == true) {
                c.searching = false;
            }
        }
    });
    $scope.$on('$destroy', function() {
        clearAllListener();
        keywordListener();
        tileListener();
        tagListener();
        showHideListener();
    });
    if (c.data.firstLoad == true) {
        c.data.firstLoad = false;
        c.updateFilters();
    }
    function isFiltered() {
        for (var h in c.filters) {
            if (c.filters[h].hasOwnProperty('value') && c.filters[h].value != '') {
                return true;
            } else if (c.filters[h].hasOwnProperty('choices') && c.filters[h].choices != '') {
                var chc = c.filters[h].choices;
                for (var i = 0; i < chc.length; i++) {
if (!chc[i].defValue && chc[i].selected) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
    function resetVals(filterName, defaultValue) {
        var filterNames = [];
        if (!filterName) {
            filterNames = Object.keys(c.filters);
        } else {
            filterNames = [filterName];
        }
        for (var name of filterNames) {
            if (c.filters[name].choices) {
                for (var choice of c.filters[name].choices) {
                    choice.selected = false;
                    if (defaultValue && choice.value == defaultValue) {
                        choice.selected = true;
                    } else if (choice.defValue === true) {
                        choice.selected = true;
                    }
                }
            }
        }
    }
};

