widget.client_script:
api.controller = function($scope, $rootScope) {
    var c = this;
    c.loading = true;
	c.isFirstLoad = true;
    if (c.data.filters && c.data.filters.opp_keyword) {
        c.keywords = c.data.filters.opp_keyword.value || '';
    }
    $scope.hasValLength = function(item) {
        return item.value && (item.value.length > 0 || (item.value.hasOwnProperty('value') && item.value.value));
    };
    $scope.catSelected = function(item) {
        return item.selected;
    };
    $scope.checkProperties = function(obj) {
        for (var key in obj) {
            if (obj[key] !== null && obj[key] != "")
                return false;
        }
        return true;
    };
    $scope.getAPage = function() {
        c.loading = true;
        c.data.getPageData = true;
        if (!c.data.filters) {
return;
        }
        c.server.update().then(function() {
			c.isFirstLoad = false;
            if (c.data.filters && c.data.filters.opp_keyword) {
                c.keywords = c.data.filters.opp_keyword.value || '';
            }
            c.data.getPageData = false;
            c.endMax = Math.min(parseInt(c.data.endLoc) + 1, parseInt(c.data.totalItems));
            c.startMax = Math.max(parseInt(c.data.startLoc), 1);
            if (c.data.sortOrder) {
                $scope.sortOrderDisplay = c.data.sortOrder.field + ',' + c.data.sortOrder.direction;
            }

            $scope.pageSizeDisplay = c.data.page_size;
			c.loading = false;
        });
    };
    $scope.pageChange = function(page) {
        var newPage = parseInt(page) || 1;
        c.data.currentPage = page;
        if (page == 0) {
            c.data.startLoc = 0;
            c.data.endLoc = c.data.page_size;
            c.data.limit = page;
        } else {
            var pageRecs = page - 1;
            c.data.startLoc = pageRecs * c.data.page_size;
            c.data.endLoc = parseInt(c.data.startLoc) + parseInt(c.data.page_size - 1);
        }
        $scope.getAPage();
    };
    $scope.clearTag = function(tag, element) {
        $rootScope.$broadcast('op.filter.update', tag);
    };
    $scope.tileViewUpdate = function(value) {
        $rootScope.$broadcast('op.tileview.update', value);
    };
    $scope.changePageSize = function(value) {
        if (value != c.data.page_size) {
            c.data.page_size = value;
$scope.pageChange(1);
        }
    };
    $scope.sortOrder = function(value) {
        var ord = value.split(',');
        c.data.sortOrder = {
            'field': ord[0],
            'direction': ord[1]
        };
        $scope.pageChange(1);
    };
    var updateListener = $rootScope.$on('op.filter.updated', function(event, data) {
        c.data.filters = data;
        c.data.tiles = c.data.filters.tiles;
        $scope.pageChange(1);
    });
    c.kwSearch = function(keywords, action) {
        if (action && action == 'remove') {
            keywords = c.data.filters.opp_keyword.value.replace(keywords, '');
        }
        $rootScope.$broadcast('op.keyword.update', keywords);
    };
    $scope.clearTag = function(tag, element) {
        $rootScope.$broadcast('op.tag.update', {
            'tag': tag,
            'element': element
        });
    };
    $scope.clearFilter = function() {
        $rootScope.$broadcast('op.clearall.update');
    };
    $scope.showhideFilter = function() {
        $rootScope.$broadcast('op.showhidefilter');
    };
    if (c.isFirstLoad == true) {
        $scope.pageChange(c.data.currentPage);
    }
    $scope.$on('$destroy', function() {
        updateListener();
    });
};

